create table if not exists public.email_delivery_log (id uuid primary key default gen_random_uuid(),notification_type text not null check(notification_type in('task_assignment','daily_digest','expiry_alert','manual')),recipient_name text,recipient_email text not null,subject text not null,status text not null check(status in('sending','sent','failed','skipped')),provider_message_id text,error_message text,related_entity_type text,related_entity_id uuid,source_table text,source_notification_id uuid,sent_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(source_table,source_notification_id));
create index if not exists email_delivery_log_created_at_idx on public.email_delivery_log(created_at desc);
create index if not exists email_delivery_log_sent_by_idx on public.email_delivery_log(sent_by) where sent_by is not null;
alter table public.email_delivery_log enable row level security;grant select,insert,update on public.email_delivery_log to authenticated;
create policy "Active users can read email delivery log" on public.email_delivery_log for select to authenticated using(exists(select 1 from public.profiles where profiles.id=(select auth.uid()) and profiles.is_active));
create policy "Active users can create email delivery log" on public.email_delivery_log for insert to authenticated with check(notification_type in('manual','task_assignment') and sent_by=(select auth.uid()) and exists(select 1 from public.profiles where profiles.id=(select auth.uid()) and profiles.is_active));
create policy "Active users can update their manual email log" on public.email_delivery_log for update to authenticated using(notification_type='manual' and sent_by=(select auth.uid())) with check(notification_type='manual' and sent_by=(select auth.uid()));
